local loading={}local gfx,theme,C local active=false local frames,progress=0,0 local function colours()if C then return C.face or 18,C.text or 27,C.accent or 29,C.bevelMid or 22 end return 18,27,29,22 end local function draw(label,fraction)local W,H=gfx.size()local bg,fg,accent,track=colours()gfx.resetClip()gfx.clear(bg)local title="CC-Windows"local titleScale=W>=120 and 2 or 1 local tw=gfx.textWidth(title,titleScale)gfx.text(math.floor((W-tw)/2),math.floor(H/2)-34,title,fg,nil,titleScale)local sub=tostring(label or"Starting")if#sub>34 then sub=sub:sub(1,31).."..."end local sw=gfx.textWidth(sub)gfx.text(math.floor((W-sw)/2),math.floor(H/2)-8,sub,fg)local bw=math.min(180,math.max(40,W-40))local bx=math.floor((W-bw)/2)local by=math.floor(H/2)+10 gfx.fill(bx,by,bw,7,track)gfx.rect(bx,by,bw,7,accent)fraction=math.max(0,math.min(1,tonumber(fraction)or 0))local fillW=math.floor((bw-2)*fraction)if fillW>0 then gfx.fill(bx+1,by+1,fillW,5,accent)end gfx.present()end function loading.begin(g,t)gfx,theme=g,t C=t and t.C or nil active=gfx~=nil and type(gfx.present)=="function"if active then loading.step("Starting CC-Windows",0)end end function loading.step(label,fraction)if not active or not gfx then return end local ok=pcall(draw,label,fraction)if ok then frames=frames+1 progress=math.max(0,math.min(1,tonumber(fraction)or 0))else active=false end end function loading.finish()active=false end function loading.active()return active end function loading.frames()return frames end function loading.progress()return progress end return loading